__NUXT_JSONP__("/de/how-to-apply/student-visa-f1/transfer-students", (function(a){return {data:[{details:{slug:"de",pageTitle:"Transfer Students | Mentor Language Institute",pageDescription:a,title:"Transfer Students",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Ftransfer-students.jpg",section:[{description:[a]}],category:[{title:"Bewerbungsschritte",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-steps-de.png",listType:"decimal",lists:["Bewirb dich am MLI (Fülle die Online Bewerbung aus)","Reiche deine Begleitdokumente ein","Nimm an der Orientierung für neue Studenten teil","Erhalte ein neues I-20"],description:["Studenten sollten sich 1 oder 2 Monate vor dem gewünschten Programmbeginn am MLI bewerben. Nachdem du deine Online-Bewerbung eingereicht hast, kontaktierst du am besten einen Studienberater beim MLI, um den Transfervorgang zu bestätigen, da es abhängig von deiner Situation manchmal kompliziert sein kann."],hasApplyNow:true},{title:"Stornierungsbedingungen",description:["Die Anmeldegebühr von $150 wird zum Zeitpunkt der Bewerbung fällig. Die Anmeldegebühr wird nicht zurückerstattet, unabhängig davon, ob ein Visumantrag abgelehnt oder die Einschreibung storniert wird."]},{title:"Nach dem Absenden deiner Bewerbung",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-form-en.jpg",description:["Nachdem die Studenten die Online Bewerbung eingereicht haben, wird MLI die Bewerbung bearbeiten und Ihnen einen Link für iMLI (die Online-Bewerbungsseite jedes Studenten) senden. Studenten können den Bewerbungsprozess auf dem iMLI verfolgen."]}],applyOnline:{title:"Bewirb dich online",description:["Fülle die Online Bewerbung aus.\u003Cbr \u002F\u003EKontaktiere uns per e-mail für Anliegen jeglicher Art."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapply-now-de.png",link:"\u002Fde\u002Fadmission"}},dir:"\u002Ftransfer-students",path:"\u002Ftransfer-students\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:31.272Z",updatedAt:"2025-05-26T12:06:27.945Z"}}],fetch:{},mutations:void 0}}("Studenten, die zur Zeit an einer anderen Schule in den USA studieren und die Schule wechseln möchten.")));